// SPDX-License-Identifier: GPL-3.0-only
'use strict';
// What changed, shown once in the window after an update (app.js, whatsNew). Newest first; every version has its
// points in each language. Add the new version's entry here with each release.
const WHATSNEW = [
  { v: '0.4.37',
    en: ['Lian Li wireless fans: groups are no longer marked as bound to another receiver when the receiver does not name itself in its reply.', 'When a wireless fan’s speed reads 0 or comes back, the receiver’s whole reply goes to the log, to find why some groups show 0 rpm while they spin.'],
    ru: ['Беспроводные вентиляторы Lian Li: группы больше не помечаются как привязанные к другому приёмнику, если приёмник не называет себя в ответе.', 'Когда обороты беспроводного вентилятора становятся 0 или возвращаются, весь ответ приёмника пишется в журнал: так найдём, почему у некоторых групп 0 об/мин, хотя они крутятся.'],
    fr: ['Ventilateurs sans fil Lian Li : les groupes ne sont plus marqués comme liés à un autre récepteur quand le récepteur ne se nomme pas dans sa réponse.', 'Quand la vitesse d’un ventilateur sans fil passe à 0 ou revient, toute la réponse du récepteur va au journal, pour trouver pourquoi certains groupes affichent 0 tr/min alors qu’ils tournent.'] },
  { v: '0.4.36',
    en: ['Lian Li wireless fans: when haku cannot read the receiver, the log now says why: the step that failed, the receiver’s first replies as they came, and its error codes. Send the diagnostics if your fans do not show up.', 'The diagnostics list L-Connect among the lighting programs running.'],
    ru: ['Беспроводные вентиляторы Lian Li: если haku не может прочитать приёмник, в журнале теперь видно почему: шаг, на котором не получилось, первые ответы приёмника как есть и коды ошибок. Если вентиляторы не появились, пришлите диагностику.', 'Диагностика показывает L-Connect среди запущенных программ подсветки.'],
    fr: ['Ventilateurs sans fil Lian Li : quand haku ne peut pas lire le récepteur, le journal dit maintenant pourquoi : l’étape qui a échoué, les premières réponses du récepteur telles quelles et ses codes d’erreur. Envoyez le diagnostic si vos ventilateurs n’apparaissent pas.', 'Le diagnostic cite L-Connect parmi les programmes d’éclairage en cours.'] },
  { v: '0.4.35',
    en: ['Lian Li wireless fans (UNI FAN TL/SL Wireless) on the Fans page: the speed and duty of each fan, as their USB receiver hears them. Read only for now: control comes next.', 'While L-Connect holds the receiver, the page says so: quit L-Connect and stop its service to read the fans in haku.'],
    ru: ['Беспроводные вентиляторы Lian Li (UNI FAN TL/SL Wireless) на странице «Вентиляторы»: обороты и заполнение каждого, как их слышит USB-приёмник. Пока только чтение: управление будет следующим.', 'Пока приёмник занят L-Connect, страница так и пишет: закройте L-Connect и остановите его службу, чтобы читать вентиляторы в haku.'],
    fr: ['Les ventilateurs sans fil Lian Li (UNI FAN TL/SL Wireless) sur la page Ventilateurs : vitesse et rapport cyclique de chacun, tels que leur récepteur USB les entend. Lecture seule pour l’instant : le pilotage viendra ensuite.', 'Tant que L-Connect tient le récepteur, la page le dit : quittez L-Connect et arrêtez son service pour lire les ventilateurs dans haku.'] },
  { v: '0.4.34',
    en: ['Fans on a fixed speed stay put again: the CPU temperature is now read only while a curve follows it.', 'A fan whose source was never chosen follows the GPU again, as before 0.4.33. The CPU stays one click away in the fan’s settings.'],
    ru: ['Вентиляторы на фиксированной скорости снова держат её: температура процессора теперь читается, только пока за ней следует кривая.', 'Вентилятор, у которого источник не выбирали, снова следует за видеокартой, как до 0.4.33. Процессор по-прежнему можно выбрать в настройках вентилятора.'],
    fr: ['Les ventilateurs à vitesse fixe s’y tiennent de nouveau : la température du processeur n’est lue que pendant qu’une courbe la suit.', 'Un ventilateur dont la source n’a jamais été choisie suit de nouveau la carte graphique, comme avant 0.4.33. Le processeur reste à un clic dans ses réglages.'] },
  { v: '0.4.33',
    en: ['Fan curves can follow the CPU temperature (AMD Ryzen and Intel Core, through PawnIO). A fan whose source was never chosen now follows the CPU where it reads, else the GPU.', 'GPU temperature on AMD and Intel cards too, read from Windows (as Task Manager shows it): no more “no sensor” on them.', 'Without a QUADRO, the Fans page speaks only of the board’s headers.'],
    ru: ['Кривые вентиляторов могут следовать за температурой процессора (AMD Ryzen и Intel Core, через PawnIO). Вентилятор, у которого источник не выбирали, теперь следует за процессором, если он читается, иначе за видеокартой.', 'Температура видеокарты теперь и на картах AMD и Intel, берётся из Windows (как в Диспетчере задач): больше никакого «нет датчика» на них.', 'Без QUADRO страница «Вентиляторы» говорит только о разъёмах платы.'],
    fr: ['Les courbes des ventilateurs peuvent suivre la température du processeur (AMD Ryzen et Intel Core, via PawnIO). Un ventilateur dont la source n’a jamais été choisie suit maintenant le processeur s’il se lit, sinon la carte graphique.', 'Température de la carte graphique aussi sur les cartes AMD et Intel, lue depuis Windows (comme le Gestionnaire des tâches) : plus de « pas de sonde » sur elles.', 'Sans QUADRO, la page Ventilateurs ne parle que des connecteurs de la carte.'] },
  { v: '0.4.32',
    en: ['Board fans (beta): on boards with a Nuvoton Super I/O chip (NCT6779D to NCT6799D, as on many ASUS boards), the board’s own fan headers show in Fans, next to the QUADRO’s channels or on their own, with the same curves and limits. Check them on your board before you rely on them.', 'Nothing to install by hand: the setup also puts in Microsoft’s WebView2 Runtime for the window and the PawnIO driver, on updates too, and when the PC page finds lighting only OpenRGB can reach, haku downloads OpenRGB itself (turn off “Use OpenRGB by itself” to stop that).', 'OpenRGB: a board added whole and by its connectors at once made its LEDs flash; Find devices now shows which of the two is added and hides the other.'],
    ru: ['Вентиляторы платы (бета): на платах с чипом Super I/O от Nuvoton (от NCT6779D до NCT6799D, как на многих платах ASUS) разъёмы вентиляторов самой платы появляются во «Вентиляторах», рядом с каналами QUADRO или сами по себе, с теми же кривыми и ограничениями. Проверьте их на своей плате, прежде чем на них полагаться.', 'Ничего не нужно ставить вручную: установщик сам ставит WebView2 Runtime от Microsoft для окна и драйвер PawnIO, в том числе при обновлении, а если страница ПК находит подсветку, до которой можно достать только через OpenRGB, haku сам скачивает OpenRGB (выключите «Сама использовать OpenRGB», чтобы этого не было).', 'OpenRGB: плата, добавленная целиком и по разъёмам одновременно, мигала; «Найти устройства» теперь показывает, что из двух добавлено, и скрывает другое.'],
    fr: ['Ventilateurs de la carte (bêta) : sur les cartes à puce Super I/O Nuvoton (NCT6779D à NCT6799D, comme sur beaucoup de cartes ASUS), les connecteurs de ventilateur de la carte apparaissent dans Ventilateurs, à côté des canaux du QUADRO ou seuls, avec les mêmes courbes et limites. Vérifiez-les sur votre carte avant de vous y fier.', 'Plus rien à installer à la main : l’installation ajoute aussi le WebView2 Runtime de Microsoft pour la fenêtre et le pilote PawnIO, mises à jour comprises, et quand la page PC trouve un éclairage que seul OpenRGB atteint, haku télécharge OpenRGB lui-même (désactivez « Utiliser OpenRGB automatiquement » pour l’éviter).', 'OpenRGB : une carte ajoutée entière et par ses connecteurs à la fois faisait clignoter ses LED ; Trouver les appareils montre maintenant lequel des deux est ajouté et masque l’autre.'] },
  { v: '0.4.31',
    en: ['OpenRGB devices: a new Mode setting in the device card, auto (Direct) or Static. If a board’s LEDs flicker in random colours even with few updates (seen on ASRock boards), choose Static: steady colours, changed a few times a second.'],
    ru: ['Устройства OpenRGB: новая настройка «Режим» в карточке устройства, авто (Direct) или Static. Если диоды платы мерцают случайными цветами даже при малом числе обновлений (бывает на платах ASRock), выберите Static: ровные цвета, меняются несколько раз в секунду.'],
    fr: ['Appareils OpenRGB : nouveau réglage Mode dans la fiche de l’appareil, auto (Direct) ou Static. Si les LED d’une carte scintillent de couleurs au hasard même avec peu de mises à jour (vu sur des cartes ASRock), choisissez Static : couleurs stables, changées quelques fois par seconde.'] },
  { v: '0.4.30',
    en: ['Motherboard ARGB connectors: Find devices also lists each connector as a device of its own (board name · connector), so a strip, a lit cable or fans on one connector can be added and lit on their own. If you add them, remove the whole-board device. A strip never shows up by its own name: look for the board and its connector.'],
    ru: ['ARGB-разъёмы материнской платы: «Найти устройства» показывает и каждый разъём отдельным устройством (название платы · разъём), так что ленту, подсвеченный кабель или вентиляторы на одном разъёме можно добавить и светить отдельно. Если добавите их, удалите устройство всей платы. Сама лента своим названием не появляется никогда: ищите плату и её разъём.'],
    fr: ['Connecteurs ARGB de la carte mère : Trouver les appareils liste aussi chaque connecteur comme un appareil à part (nom de la carte · connecteur), pour ajouter et éclairer à part une bande, un câble lumineux ou des ventilateurs sur un connecteur. Si vous les ajoutez, retirez l’appareil de la carte entière. Une bande n’apparaît jamais sous son propre nom : cherchez la carte et son connecteur.'] },
  { v: '0.4.29',
    en: ['ASUS boards: haku now lights the board’s own LEDs (the ROG logo, the I/O cover) itself, over its USB Aura controller: Find devices › ASUS board LEDs. If the board does not say how many LEDs it has, Calibrate finds the count. Close Armoury Crate first.', 'Calibrate: no blue at all on a connector means its count is too high.'],
    ru: ['Платы ASUS: haku теперь сам управляет подсветкой платы (логотип ROG, кожух портов) через её USB-контроллер Aura: «Найти устройства» › ASUS board LEDs. Если плата не сообщает число светодиодов, его найдёт «Калибровка». Сначала закройте Armoury Crate.', 'Калибровка: если синего на разъёме не видно совсем, число светодиодов слишком большое.'],
    fr: ['Cartes ASUS : haku allume maintenant lui-même les LED de la carte (logo ROG, cache des ports) par son contrôleur USB Aura : Trouver les appareils › ASUS board LEDs. Si la carte ne dit pas combien de LED elle a, Calibrer trouve le nombre. Fermez d’abord Armoury Crate.', 'Calibrer : pas de bleu du tout sur un connecteur, son nombre est trop grand.'] },
  { v: '0.4.28',
    en: ['Motherboard ARGB connectors light at once: one never set starts with a guessed LED count, and Calibrate finds the real one by eye, connector by connector (red on its first LED, blue on its last). A board left at 0 LEDs says it needs setup instead of looking offline.', 'TRYX: a sent picture or video waits longer for the cooler to confirm it, and is shown if the cooler took it without confirming.'],
    ru: ['ARGB-разъёмы материнской платы светятся сразу: у ненастроенного стоит примерное число светодиодов, а «Калибровка» находит точное на глаз, разъём за разъёмом (красный на первом светодиоде, синий на последнем). Плата с 0 светодиодов пишет «нужна настройка», а не выглядит отключённой.', 'TRYX: отправленная картинка или видео дольше ждёт подтверждения от кулера и показывается, если кулер принял файл, но не подтвердил.'],
    fr: ['Les connecteurs ARGB de la carte mère s’allument tout de suite : un connecteur jamais réglé part d’un nombre de LED estimé, et Calibrer trouve le vrai à l’œil, connecteur par connecteur (rouge sur sa première LED, bleu sur la dernière). Une carte restée à 0 LED indique qu’elle est à configurer au lieu de paraître hors ligne.', 'TRYX : une image ou vidéo envoyée attend plus longtemps la confirmation du refroidisseur, et s’affiche s’il l’a reçue sans confirmer.'] },
  { v: '0.4.27',
    en: ['Groups: choosing Colour or a colour swatch no longer closes the group window.', 'A bug report and the diagnostics file now list the other lighting programs running (Armoury Crate, iCUE, SignalRGB…), which can keep a board or controller from haku.'],
    ru: ['Группы: выбор «Цвет» или образца цвета больше не закрывает окно группы.', 'Отчёт о проблеме и файл диагностики теперь показывают другие запущенные программы подсветки (Armoury Crate, iCUE, SignalRGB…), которые могут не давать haku доступ к плате или контроллеру.'],
    fr: ['Groupes : choisir Couleur ou un échantillon de couleur ne ferme plus la fenêtre du groupe.', 'Le rapport de problème et le fichier de diagnostic listent maintenant les autres logiciels d’éclairage en cours (Armoury Crate, iCUE, SignalRGB…), qui peuvent empêcher haku d’accéder à une carte ou un contrôleur.'] },
  { v: '0.4.26',
    en: ['TRYX: your own video now shows on the PANORAMA (it was sent with a picture shape the cooler does not know); the card shows the sending progress.', 'The TRYX card is the screen only now: theme, your picture or video. The cooler’s fan lights are set on the motherboard’s card, where they are connected.'],
    ru: ['TRYX: своё видео теперь показывается на PANORAMA (оно отправлялось с соотношением сторон, которого кулер не знает); карточка показывает ход отправки.', 'Карточка TRYX теперь только про экран: тема, своя картинка или видео. Подсветка вентиляторов кулера настраивается в карточке материнской платы, куда она подключена.'],
    fr: ['TRYX : votre vidéo s’affiche maintenant sur le PANORAMA (elle partait avec un format d’image que le refroidisseur ne connaît pas) ; la carte montre la progression de l’envoi.', 'La carte TRYX ne concerne plus que l’écran : thème, votre image ou vidéo. Les LED des ventilateurs du refroidisseur se règlent sur la carte de la carte mère, où elles sont branchées.'] },
  { v: '0.4.25',
    en: ['TRYX PANORAMA and 240 SE (beta): show your own picture, GIF or mp4 on the cooler’s screen. In Devices pick “Your picture or video” and choose a file (up to 16 MB). It goes over the cable slowly, about 10 KB/s, and only once; the card shows the progress. Close TRYX KANALI first.'],
    ru: ['TRYX PANORAMA и 240 SE (бета): своя картинка, GIF или mp4 на экране кулера. В «Устройствах» выберите «Своя картинка или видео» и файл (до 16 МБ). Он идёт по кабелю медленно, около 10 КБ/с, и только один раз; карточка показывает прогресс. Сначала закройте TRYX KANALI.'],
    fr: ['TRYX PANORAMA et 240 SE (bêta) : votre image, GIF ou mp4 sur l’écran du refroidisseur. Dans Appareils, choisissez « Votre image ou vidéo » puis un fichier (16 Mo au plus). Il passe lentement par le câble, environ 10 Ko/s, et une seule fois ; la carte montre la progression. Fermez d’abord TRYX KANALI.'] },
  { v: '0.4.24',
    en: ['iCUE LINK (beta, read only): turn it on in the PC tab to see the RPM and temperature of each device on the hub, and the Corsair power supply’s voltages, currents and watts. Close iCUE first: while it runs, the card says so and haku leaves the hub alone.', 'OpenRGB: two RAM sticks of one kit, which share a name, are both added now.'],
    ru: ['iCUE LINK (бета, только чтение): включите на вкладке ПК, чтобы видеть обороты и температуру каждого устройства на хабе, а также напряжение, ток и мощность блока питания Corsair. Сначала закройте iCUE: пока он работает, карточка об этом говорит, и haku не трогает хаб.', 'OpenRGB: две планки памяти из одного комплекта с одинаковым названием теперь добавляются обе.'],
    fr: ['iCUE LINK (bêta, lecture seule) : activez-le dans l’onglet PC pour voir les tr/min et la température de chaque appareil du hub, ainsi que les tensions, courants et watts de l’alimentation Corsair. Fermez d’abord iCUE : tant qu’il tourne, la carte le dit et haku laisse le hub tranquille.', 'OpenRGB : deux barrettes d’un même kit, qui portent le même nom, sont maintenant ajoutées toutes les deux.'] },
  { v: '0.4.23',
    en: ['Fans (beta): if the QUADRO’s own settings cannot be saved, haku leaves the channel as it is and says why; the emergency speed shows the reason, the % and whether the QUADRO confirmed it.', 'Curve editor: edits wait for Apply, Cancel sends nothing; 2 to 8 points with the mouse, the keys or exact numbers; each temperature source keeps its own curve, and Reset gives its default. The chart shows what the fan really gets, with its floor.', 'Save curves by name and use them on any fan; the fan keeps its own limits.', 'History: asked and read-back speed, RPM and temperature with time labels, values under the pointer, lines on and off, and marks for a source change, a lost link and the emergency speed. Groups open to show what is shared and what differs.'],
    ru: ['Вентиляторы (бета): если собственные настройки QUADRO не удалось сохранить, haku не трогает канал и объясняет почему; аварийная скорость показывает причину, процент и подтвердил ли её QUADRO.', 'Редактор кривой: правки ждут кнопки «Применить», «Отменить» ничего не отправляет; от 2 до 8 точек мышью, клавишами или точными числами; у каждого источника температуры своя кривая, «Сбросить» возвращает его кривую по умолчанию. График показывает, что вентилятор получает на самом деле, с учётом минимума.', 'Кривые можно сохранять под именем и ставить на любой вентилятор; его ограничения при этом не меняются.', 'История: заданная и считанная скорость, обороты и температура с подписями времени, значения под указателем, линии можно скрыть, отметки смены источника, потери связи и аварийной скорости. Группы раскрываются и показывают общие и различающиеся настройки.'],
    fr: ['Ventilateurs (bêta) : si les réglages propres du QUADRO ne peuvent pas être gardés, haku laisse le canal tel quel et dit pourquoi ; la vitesse de secours indique la raison, le % et si le QUADRO l’a confirmée.', 'Éditeur de courbe : les modifications attendent Appliquer, Annuler n’envoie rien ; de 2 à 8 points à la souris, au clavier ou en valeurs exactes ; chaque source de température garde sa courbe, et Réinitialiser remet celle par défaut. Le graphique montre ce que reçoit vraiment le ventilateur, plancher compris.', 'Enregistrez des courbes sous un nom et utilisez-les sur n’importe quel ventilateur ; il garde ses propres limites.', 'Historique : vitesse demandée et relue, tr/min et température avec les heures, valeurs sous le pointeur, lignes à afficher ou masquer, et repères pour un changement de source, une liaison perdue et la vitesse de secours. Les groupes s’ouvrent et montrent ce qui est commun et ce qui diffère.'] },
  { v: '0.4.22',
    en: ['Fans (beta): if a curve loses its temperature, the fan runs at its own emergency speed (100% unless you set it) and the card says why: no sensor, an old reading or no link to the QUADRO.', 'Each fan card shows the RPM first, then what haku asked for and whether the QUADRO confirmed it; write errors are shown, not hidden. If the QUADRO drops off USB, the page stays with “No connection”.', 'The QUADRO’s own settings are kept per device, so they come back after a USB drop, sleep, exit or the next start after a crash. “Give every channel back to the QUADRO” says if it worked.', 'Curve editor: a bigger graph, exact numbers for the selected point, the source with its temperature, renamable sensors, a 5-minute history, and a floor and emergency speed per fan or pump.'],
    ru: ['Вентиляторы (бета): если кривая теряет температуру, вентилятор переходит на свою аварийную скорость (100%, если не задано иначе), а карточка объясняет причину: нет датчика, данные устарели или нет связи с QUADRO.', 'На карточке сначала обороты, затем что попросил haku и подтвердил ли QUADRO; ошибки записи видны, а не скрыты. Если QUADRO пропал с USB, страница остаётся с надписью «Нет связи».', 'Собственные настройки QUADRO хранятся отдельно для каждого устройства и возвращаются после обрыва USB, сна, выхода или при следующем запуске после сбоя. «Вернуть все каналы QUADRO» сообщает, получилось ли.', 'Редактор кривой: график крупнее, точные значения выбранной точки, источник с температурой, датчики можно переименовать, история за 5 минут, свой минимум и аварийная скорость для вентилятора или помпы.'],
    fr: ['Ventilateurs (bêta) : si une courbe perd sa température, le ventilateur passe à sa vitesse de secours (100 % sauf réglage) et la carte en donne la raison : pas de capteur, lecture trop ancienne ou plus de liaison avec le QUADRO.', 'Chaque carte affiche d’abord les tr/min, puis ce que haku a demandé et si le QUADRO l’a confirmé ; les erreurs d’écriture sont affichées. Si le QUADRO disparaît de l’USB, la page reste avec « Pas de connexion ».', 'Les réglages propres du QUADRO sont gardés pour chaque appareil et reviennent après une coupure USB, la veille, la fermeture ou au démarrage suivant après un plantage. « Rendre tous les canaux au QUADRO » indique si cela a marché.', 'Éditeur de courbe : un graphique plus grand, les valeurs exactes du point choisi, la source avec sa température, des capteurs renommables, un historique de 5 minutes, et un minimum et une vitesse de secours par ventilateur ou pompe.'] },
  { v: '0.4.21',
    en: ['Fans: a panel of tiles. Click a fan or a group to open its settings in a window.', 'Groups: put fans together and set them all at once.', 'Rename a fan (say, Pump) or a group; take a fan you do not have off the panel and put it back any time.'],
    ru: ['Вентиляторы: теперь это панель плиток. Нажмите на вентилятор или группу, и настройки откроются в окне.', 'Группы: соберите вентиляторы вместе и настраивайте их все сразу.', 'Вентилятор (например, помпу) и группу можно переименовать; лишний вентилятор убирается с панели и возвращается в любой момент.'],
    fr: ['Ventilateurs : un panneau de tuiles. Cliquez sur un ventilateur ou un groupe pour ouvrir ses réglages dans une fenêtre.', 'Groupes : réunissez des ventilateurs et réglez-les tous à la fois.', 'Renommez un ventilateur (une pompe, par exemple) ou un groupe ; retirez du panneau un ventilateur que vous n’avez pas et remettez-le quand vous voulez.'] },
  { v: '0.4.20',
    en: ['Fans: a new tab for the Aqua Computer QUADRO. Each fan stays as is, runs at a fixed speed or follows a curve by the GPU or a QUADRO sensor; drag the points or use the arrow keys. Never below 20%, and the QUADRO gets its own settings back when haku closes or the PC sleeps. Experimental: reports are very welcome.', 'The QUADRO’s water temperature now feeds the Temperature effect.', 'TRYX PANORAMA: when TRYX KANALI holds the port, the card says so.'],
    ru: ['Вентиляторы: новая вкладка для Aqua Computer QUADRO. Каждый вентилятор работает как есть, на постоянной скорости или по кривой от видеокарты или датчика QUADRO; точки перетаскиваются мышью или стрелками. Не ниже 20%, а когда haku закрывается или ПК засыпает, QUADRO получает свои настройки обратно. Экспериментально: отчёты очень помогут.', 'Температура воды с QUADRO теперь идёт в эффект «Температура».', 'TRYX PANORAMA: если порт занят TRYX KANALI, карточка так и говорит.'],
    fr: ['Ventilateurs : un nouvel onglet pour l’Aqua Computer QUADRO. Chaque ventilateur reste tel quel, tourne à vitesse fixe ou suit une courbe selon la carte graphique ou une sonde du QUADRO ; faites glisser les points ou utilisez les flèches. Jamais sous 20 %, et le QUADRO retrouve ses propres réglages quand haku se ferme ou que le PC se met en veille. Expérimental : vos retours sont les bienvenus.', 'La température de l’eau du QUADRO alimente maintenant l’effet Température.', 'TRYX PANORAMA : quand TRYX KANALI occupe le port, la fiche le dit.'] },
  { v: '0.4.19',
    en: ['Restoring a backup is safer still: if a profile cannot be swapped in, every profile and setting goes back as it was. Duplicate works from the phone too.', 'A setting changed while a device is offline says it is saved only when it will really apply once the device is back; otherwise you see what is going on.', 'The names in the offline list open that device’s card, from the mouse or the keyboard.', 'A calmer window: Find devices, the theme code behind a small Code button, the PC hardware details folded, and no Pro chip on the phone’s brightness bar.'],
    ru: ['Восстановление из резервной копии ещё надёжнее: если профиль не удаётся заменить, все профили и настройки возвращаются как были. «Дублировать» работает и с телефона.', 'Если изменить настройку устройства без связи, сообщение «Сохранено» появится, только когда она действительно применится после подключения; иначе видно, что происходит.', 'Названия в списке устройств без связи открывают карточку устройства — мышью или с клавиатуры.', 'Окно спокойнее: «Найти устройства», код темы — за маленькой кнопкой «Код», подробности о железе ПК свёрнуты, а на полосе яркости в телефоне нет значка Pro.'],
    fr: ['Restaurer une sauvegarde est encore plus sûr : si un profil ne peut pas être remplacé, tous les profils et réglages reviennent comme avant. Dupliquer marche aussi depuis le téléphone.', 'Un réglage modifié pendant qu’un appareil est injoignable n’indique « Enregistré » que s’il sera vraiment appliqué au retour de l’appareil ; sinon vous voyez ce qui se passe.', 'Les noms de la liste des appareils injoignables ouvrent la fiche de l’appareil, à la souris ou au clavier.', 'Une fenêtre plus calme : Trouver les appareils, le code du thème derrière un petit bouton Code, les détails du matériel du PC repliés, et plus de puce Pro sur la barre de luminosité du téléphone.'] },
  { v: '0.4.18',
    en: ['TRYX PANORAMA coolers: the screen is found on USB by Scan network (close TRYX KANALI first). Pick one of its built-in themes; its brightness follows haku’s, and it turns off with the lights. Experimental: reports from owners are very welcome.'],
    ru: ['Кулеры TRYX PANORAMA: экран находится по USB через «Найти в сети» (сначала закройте TRYX KANALI). Можно выбрать одну из встроенных тем; яркость следует за яркостью haku, а экран гаснет вместе со светом. Экспериментально: отчёты владельцев очень помогут.'],
    fr: ['Refroidisseurs TRYX PANORAMA : l’écran est trouvé en USB par Analyser le réseau (fermez d’abord TRYX KANALI). Choisissez l’un de ses thèmes intégrés ; sa luminosité suit celle de haku, et il s’éteint avec la lumière. Expérimental : les retours des propriétaires sont les bienvenus.'] },
  { v: '0.4.17',
    en: ['A profile’s time can be set for some days of the week and switched off; two profiles at the same time are pointed out, and Duplicate copies a profile.', 'The profile menu says why a profile is on (your choice, its time or its program), and auto-switching can be paused.', 'On a phone the bar at the bottom keeps Effects, Devices and Settings, and the kinds of devices are a row at the top of Devices; the phone page catches up with every change made on the PC.', 'Restoring a backup is all or nothing: a damaged file or a failed write leaves your settings as they were. A profile switch no longer jumps when a device goes on or off.', 'Settings start with the everyday ones, Cancel buttons are calmer, the calibration guide says what a device cannot set, and the intro plays only the first time the window opens.'],
    ru: ['Время профиля можно задать по дням недели и выключить; если у двух профилей одно время, это видно, а «Дублировать» копирует профиль.', 'Меню профилей говорит, почему профиль включён (ваш выбор, его время или его программа), а автопереключение можно поставить на паузу.', 'На телефоне внизу остаются «Эффекты», «Устройства» и «Настройки», а виды устройств — строкой вверху «Устройств»; страница на телефоне подхватывает любые изменения, сделанные на ПК.', 'Восстановление из резервной копии — всё или ничего: повреждённый файл или ошибка записи оставляют настройки как были. Переход между профилями больше не скачет, когда устройство включается или выключается.', 'Настройки начинаются с повседневных, кнопки «Отмена» спокойнее, мастер калибровки объясняет, что у устройства нельзя настроить, а заставка играет только при первом открытии окна.'],
    fr: ['L’heure d’un profil peut se régler pour certains jours de la semaine et se couper ; deux profils à la même heure sont signalés, et Dupliquer copie un profil.', 'Le menu des profils dit pourquoi un profil est actif (votre choix, son heure ou son programme), et le changement automatique peut être mis en pause.', 'Sur un téléphone, la barre du bas garde Effets, Appareils et Réglages, et les types d’appareils forment une rangée en haut d’Appareils ; la page du téléphone suit chaque changement fait sur le PC.', 'Restaurer une sauvegarde, c’est tout ou rien : un fichier abîmé ou une écriture ratée laisse vos réglages tels quels. Le passage d’un profil à l’autre ne saute plus quand un appareil s’allume ou s’éteint.', 'Les réglages commencent par ceux de tous les jours, les boutons Annuler sont plus discrets, le guide de calibrage dit ce qu’un appareil ne peut pas régler, et l’intro ne se joue qu’à la première ouverture de la fenêtre.'] },
  { v: '0.4.16',
    en: ['Undo: Ctrl+Z, or the button that shows up after a change, puts back the last setting, effect or brightness.', 'Each device has a calibration guide: where its LEDs end, which way effects run and how warm its white is.', 'Check connection reconnects right away and says why a device does not answer.', 'Profiles can come on every day at a set time, pinned ones get a quick button next to the switcher, and switching blends over in under a second instead of jumping.', 'The Lights caption in the sidebar folds the brand tabs away, all but the one open; the preview’s devices are reachable with Tab, and Enter opens a device’s settings.'],
    ru: ['Отмена: Ctrl+Z или кнопка, которая появляется после изменения, возвращает последнюю настройку, эффект или яркость.', 'У каждого устройства есть мастер калибровки: где кончаются светодиоды, в какую сторону бегут эффекты и насколько тёплый белый.', '«Проверить связь» переподключается сразу и объясняет, почему устройство не отвечает.', 'Профили могут включаться каждый день в заданное время, у закреплённых есть быстрая кнопка рядом с переключателем, а переход плавный, меньше секунды, вместо скачка.', 'Подпись «Свет» в боковой панели сворачивает вкладки брендов, кроме открытой; устройства в превью доступны по Tab, а Enter открывает их настройки.'],
    fr: ['Annuler : Ctrl+Z, ou le bouton qui apparaît après un changement, remet le dernier réglage, effet ou luminosité.', 'Chaque appareil a un guide de calibrage : où finissent ses LED, dans quel sens vont les effets et la chaleur de son blanc.', 'Vérifier la connexion se reconnecte tout de suite et dit pourquoi un appareil ne répond pas.', 'Les profils peuvent s’allumer chaque jour à une heure fixe, ceux épinglés ont un bouton rapide à côté du sélecteur, et le passage se fond en moins d’une seconde au lieu de sauter.', 'La légende Lumières de la barre latérale replie les onglets des marques, sauf celui ouvert ; les appareils de l’aperçu sont accessibles avec Tab, et Entrée ouvre leurs réglages.'] },
  { v: '0.4.15',
    en: ['New device pictures on the Effects tab: memory sticks lie down with their light inside, a full keyboard, a gaming mouse with its RGB strips, a key light on a pole, Times Gate as a bar of five screens and Times Frame glowing on the wall.'],
    ru: ['Новые картинки устройств на вкладке «Эффекты»: плашки памяти лежат, свет у них внутри, полная клавиатура, игровая мышь со своими RGB-полосками, лампа для стрима на стойке, Times Gate в виде пяти экранов и Times Frame, светящаяся на стене.'],
    fr: ['Nouvelles images des appareils dans l’onglet Effets : les barrettes de mémoire sont couchées avec leur lumière à l’intérieur, un clavier complet, une souris gaming avec ses bandes RGB, une lampe de stream sur pied, Times Gate en barre de cinq écrans et Times Frame qui brille au mur.'] },
  { v: '0.4.14',
    en: ['A calmer look: effect cards glow softly from their bottom edge, markers are small diamonds, and the menu, power and timer icons are drawn with straight lines.', 'The devices on the Effects tab have new pictures: flat and sharp, with a real bulb, a mouse, a framed fan and a clean glow on the light bars.', 'Delete, Cancel, Forget and Remove buttons are red, and buttons fill from the left when you point at them.'],
    ru: ['Спокойнее на вид: карточки эффектов мягко светятся от нижнего края, метки стали маленькими ромбами, а иконки меню, питания и таймера нарисованы прямыми линиями.', 'У устройств на вкладке «Эффекты» новые картинки: плоские и чёткие, с настоящей лампочкой, мышью, вентилятором в рамке и чистым свечением световых полос.', 'Кнопки «Удалить», «Отмена», «Забыть» и «Убрать» красные, а кнопки заполняются слева при наведении.'],
    fr: ['Un aspect plus calme : les cartes d’effets brillent doucement depuis leur bord inférieur, les repères sont de petits losanges, et les icônes du menu, de l’alimentation et de la minuterie sont tracées en lignes droites.', 'Les appareils de l’onglet Effets ont de nouvelles images : plates et nettes, avec une vraie ampoule, une souris, un ventilateur dans son cadre et une lueur nette sur les barres lumineuses.', 'Les boutons Supprimer, Annuler, Oublier et Retirer sont rouges, et les boutons se remplissent depuis la gauche au survol.'] },
  { v: '0.4.13',
    en: ['The buttons of the preset and group windows line up: Delete and Share are the same size as the others and sit on the same line.'],
    ru: ['Кнопки в окнах пресета и группы стоят ровно: «Удалить» и «Поделиться» того же размера, что и остальные, и на одной линии с ними.'],
    fr: ['Les boutons des fenêtres de préréglage et de groupe sont alignés : Supprimer et Partager ont la même taille que les autres, sur la même ligne.'] },
  { v: '0.4.12',
    en: ['A sleep timer: the clock next to the power button turns the lights off in 15, 30, 60 or 120 minutes, fading them out over the last minute.', 'Not sure which light is which? "Blink" flashes it white for a few seconds, from its window or its card.', 'The window of a device has a group picker, so you can put it in a group with a tap instead of dragging it.', 'The status at the top says what is wrong ("1 offline") and a click on it shows which devices do not answer.', 'The preview on the Effects tab shows one row and opens fully with "Show all"; a device card keeps its technical settings under "Advanced".', 'Cancelling the group window now puts everything back as it was, the look of the lights included.'],
    ru: ['Таймер сна: часы рядом с кнопкой питания выключат свет через 15, 30, 60 или 120 минут, плавно погасив его за последнюю минуту.', 'Не помните, какое устройство где? Кнопка «Мигнуть» на пару секунд мигает им белым — в его окне или на карточке.', 'В окне устройства есть выбор группы: добавить его в группу можно нажатием, без перетаскивания.', 'Статус вверху говорит, что не так («нет связи: 1»), а клик по нему показывает, какие устройства не отвечают.', 'Превью на вкладке «Эффекты» показывает один ряд и раскрывается кнопкой «Показать все»; технические настройки в карточке устройства убраны в «Дополнительно».', 'Отмена в окне группы теперь возвращает всё как было, включая вид подсветки.'],
    fr: ['Une minuterie : l’horloge à côté du bouton d’alimentation éteint les lumières dans 15, 30, 60 ou 120 minutes, en les faisant baisser pendant la dernière minute.', 'Vous ne savez plus quelle lumière est laquelle ? « Clignoter » la fait clignoter en blanc quelques secondes, depuis sa fenêtre ou sa carte.', 'La fenêtre d’un appareil a un choix de groupe : on l’ajoute à un groupe d’un toucher, sans le glisser.', 'L’état en haut dit ce qui ne va pas (« 1 hors ligne ») et un clic montre quels appareils ne répondent pas.', 'L’aperçu de l’onglet Effets montre une rangée et s’ouvre en entier avec « Tout afficher » ; les réglages techniques d’une carte d’appareil sont rangés sous « Avancé ».', 'Annuler la fenêtre d’un groupe remet maintenant tout comme avant, l’aspect des lumières compris.'] },
  { v: '0.4.11',
    en: ['Profiles can switch by themselves: give one a list of programs, and it turns on while one of them runs, then the previous profile comes back.', 'Effects are sorted into calm, lively and reactive, and a star puts your favourites first.', 'Your recent colours sit under the mood bar: one click brings a palette back.', 'Devices that are offline are dimmed and marked on the Effects tab, effect previews are bigger, and device names are easier to read.', 'Switches, sliders, the chosen tab and the chosen effect take the colour of your lights, and a brand page with one or two lights shows them big, settings beside them.', 'haku is lighter on the PC while its window is hidden or minimised.', 'Memory lighting works right after installing: the setup installs PawnIO, the free driver it needs, when it is missing.', 'Already using haku without PawnIO? The PC page installs it with one click, and the memory lights up without a restart.'],
    ru: ['Профили умеют включаться сами: дайте профилю список программ, и он включится, пока одна из них запущена, а потом вернётся прежний.', 'Эффекты разложены на спокойные, живые и реагирующие, а звёздочка ставит избранные первыми.', 'Недавние цвета лежат под строкой настроения: один клик возвращает палитру.', 'Устройства не в сети на вкладке «Эффекты» приглушены и подписаны, превью эффектов крупнее, названия устройств читаются легче.', 'Переключатели, ползунки, выбранная вкладка и выбранный эффект окрашиваются в цвет вашей подсветки, а страница бренда с одним-двумя устройствами показывает их крупно, с настройками рядом.', 'haku меньше нагружает ПК, пока его окно скрыто или свёрнуто.', 'Подсветка памяти работает сразу после установки: установщик сам ставит PawnIO, нужный для неё бесплатный драйвер, если его нет.', 'Уже пользуетесь haku без PawnIO? На странице «ПК» он ставится одной кнопкой, и память загорается без перезапуска.'],
    fr: ['Les profils peuvent s’activer tout seuls : donnez-leur une liste de programmes, le profil s’active tant que l’un d’eux tourne, puis le précédent revient.', 'Les effets sont rangés en calmes, vifs et réactifs, et une étoile met vos favoris en premier.', 'Vos couleurs récentes sont sous la barre d’ambiance : un clic ramène une palette.', 'Les appareils hors ligne sont atténués et signalés dans l’onglet Effets, les aperçus des effets sont plus grands et les noms des appareils se lisent mieux.', 'Les interrupteurs, les curseurs, l’onglet et l’effet choisis prennent la couleur de vos lumières, et la page d’une marque avec une ou deux lumières les montre en grand, les réglages à côté.', 'haku pèse moins sur le PC quand sa fenêtre est cachée ou réduite.', 'L\'éclairage de la mémoire marche dès l\'installation : l\'installateur installe PawnIO, le pilote gratuit dont il a besoin, s\'il manque.', 'Vous utilisez déjà haku sans PawnIO ? La page PC l\'installe en un clic, et la mémoire s\'allume sans redémarrer.'] },
  { v: '0.4.10',
    en: ['Memory sticks that went dark while another program (such as OpenRGB loading a profile) took them over are lit again by haku within two seconds, even with a still colour.', 'When the developer fixes a problem you reported with "Report a problem", haku tells you so in its window.'],
    ru: ['Планки памяти, которые гасли, когда их перехватывала другая программа (например, OpenRGB с профилем при запуске), haku снова зажигает за пару секунд, даже со статичным цветом.', 'Когда разработчик исправляет проблему, о которой вы сообщили через «Сообщить о проблеме», haku говорит вам об этом в своём окне.'],
    fr: ['Les barrettes de mémoire qui s\'éteignaient quand un autre programme (comme OpenRGB chargeant un profil) les reprenait sont rallumées par haku en deux secondes, même avec une couleur fixe.', 'Quand le développeur corrige un problème que vous avez signalé avec « Signaler un problème », haku vous le dit dans sa fenêtre.'] },
  { v: '0.4.9',
    en: ['The opening of the window now matches your theme: light in the dark on the dark theme, a softer glow on graphite with two quick glints on the grey one, and ink on paper on the light one.',
         'It plays every time the window opens, from the tray too, and it no longer stutters in its first moment.',
         'After an update, haku opens its window by itself, so you see right away that the new version is there.'],
    ru: ['Заставка окна теперь своя для каждой темы: свет в темноте в тёмной, мягкое свечение на графите с двумя быстрыми бликами в серой и чернила на бумаге в светлой.',
         'Она играет при каждом открытии окна, из трея тоже, и больше не подтормаживает в самом начале.',
         'После обновления haku сам открывает окно, так что сразу видно, что новая версия на месте.'],
    fr: ['L\'ouverture de la fenêtre suit maintenant votre thème : de la lumière dans le noir avec le thème sombre, une lueur plus douce sur du graphite avec deux reflets rapides avec le gris, et de l\'encre sur du papier avec le clair.',
         'Elle se joue à chaque ouverture de la fenêtre, depuis la zone de notification aussi, et ne saccade plus au tout début.',
         'Après une mise à jour, haku ouvre sa fenêtre tout seul : on voit tout de suite que la nouvelle version est là.'] },
  { v: '0.4.8',
    en: ['Phone control and Home Assistant are safer: every command is now checked by haku itself, and a phone can no longer change which programs haku starts (OpenRGB, Ollama) or the phone and Home Assistant settings.',
         'Saved passwords are no longer shown, in the window or on a paired phone: the Home Assistant password field stays empty with dots when one is saved, and typing a new one replaces it.',
         'The first-start wizard is shorter: the "Inside your PC" step is gone, the Devices tab already shows what haku finds.'],
    ru: ['Управление с телефона и Home Assistant стали безопаснее: каждую команду теперь проверяет сам haku, и телефон больше не может менять, какие программы запускает haku (OpenRGB, Ollama), а также настройки телефона и Home Assistant.',
         'Сохранённые пароли больше не показываются ни в окне, ни на подключённом телефоне: поле пароля Home Assistant остаётся пустым с точками, если пароль сохранён, а новый пароль просто вписывается поверх.',
         'Мастер первого запуска стал короче: шага «Внутри ПК» больше нет, всё найденное и так видно на вкладке «Устройства».'],
    fr: ['Le contrôle depuis le téléphone et Home Assistant sont plus sûrs : chaque commande est maintenant vérifiée par haku lui-même, et un téléphone ne peut plus changer les programmes que haku lance (OpenRGB, Ollama) ni les réglages du téléphone et de Home Assistant.',
         'Les mots de passe enregistrés ne sont plus affichés, ni dans la fenêtre ni sur un téléphone associé : le champ du mot de passe Home Assistant reste vide avec des points quand il y en a un, et en taper un nouveau le remplace.',
         'L\'assistant du premier démarrage est plus court : l\'étape « Dans votre PC » a disparu, l\'onglet Appareils montre déjà ce que haku trouve.'] },
  { v: '0.4.7',
    en: ['A new opening for the window: a spark lights up in the dark, opens into a star, and the star draws the haku logo\'s orbit as the letters fly in.'],
    ru: ['Новая заставка окна: в темноте вспыхивает искра, раскрывается в звезду, и звезда прочерчивает орбиту логотипа haku, пока к ней слетаются буквы.'],
    fr: ['Une nouvelle ouverture de la fenêtre : une étincelle s\'allume dans le noir, s\'ouvre en étoile, et l\'étoile trace l\'orbite du logo haku pendant que les lettres arrivent.'] },
  { v: '0.4.6',
    en: ['The window now opens with the haku logo coming together out of light, in the colours of your current effect, then flying into its place. It plays the first time the window opens after haku starts; a click or a key skips it, and it stays off with animations turned off.'],
    ru: ['Теперь окно открывается заставкой: логотип haku собирается из света в цветах текущего эффекта и улетает на своё место. Она играет при первом открытии окна после запуска haku; клик или любая клавиша её пропускают, а с выключенными анимациями её нет.'],
    fr: ['La fenêtre s\'ouvre maintenant sur le logo haku qui se forme dans la lumière, aux couleurs de l\'effet en cours, puis s\'envole à sa place. Il se joue à la première ouverture de la fenêtre après le démarrage de haku ; un clic ou une touche le passe, et il ne se joue pas si les animations sont coupées.'] },
  { v: '0.4.5',
    en: ['A new hidden theme: a night sky under the window, with twinkling and shooting stars. Those who have its code know what to type next to the theme switch.'],
    ru: ['Новая скрытая тема: ночное небо за окном, с мерцающими и падающими звёздами. У кого есть её код, тот знает, что вписать рядом с переключателем темы.'],
    fr: ['Un nouveau thème caché : un ciel de nuit sous la fenêtre, avec des étoiles qui scintillent et des étoiles filantes. Ceux qui ont son code savent quoi taper à côté du choix du thème.'] },
  { v: '0.4.4',
    en: ['Fans and strips on a motherboard\'s ARGB connectors (through OpenRGB) can now light up: the device\'s card has LEDs on each connector. OpenRGB starts these connectors at 0 LEDs, so enter how many are plugged into each; haku sets them again every time.'],
    ru: ['Вентиляторы и ленты в ARGB-разъёмах материнской платы (через OpenRGB) теперь можно зажечь: в карточке устройства появилось «Светодиодов на разъёме». OpenRGB начинает такие разъёмы с 0 светодиодов — укажите, сколько подключено к каждому, и haku будет выставлять это при каждом запуске.'],
    fr: ['Les ventilateurs et rubans branchés sur les connecteurs ARGB de la carte mère (via OpenRGB) peuvent maintenant s\'allumer : la fiche de l\'appareil a LED sur chaque connecteur. OpenRGB démarre ces connecteurs à 0 LED, indiquez donc combien sont branchées sur chacun ; haku les règle à nouveau à chaque fois.'] },
  { v: '0.4.3',
    en: ['A new effect, Colour wave: bands of your colours sweep across the whole room, every device taking the wave as it passes, like SignalRGB\'s Color Wave. Choose the direction (left, right, up, down, from or to the middle) and how long the wave is.'],
    ru: ['Новый эффект «Цветная волна»: полосы ваших цветов идут волной через всю комнату, каждое устройство подхватывает её по очереди, как Color Wave в SignalRGB. Можно выбрать направление (влево, вправо, вверх, вниз, от центра или к центру) и длину волны.'],
    fr: ['Un nouvel effet, Vague de couleurs : des bandes de vos couleurs balaient toute la pièce, chaque appareil prenant la vague à son passage, comme le Color Wave de SignalRGB. Choisissez la direction (gauche, droite, haut, bas, depuis ou vers le centre) et la longueur de la vague.'] },
  { v: '0.4.2',
    en: ['Report a problem, right from the app: Settings → Report a problem. Say what happened, and it goes straight to the developer with the diagnostics (no keys, tokens or passwords). You can leave a way to reach you, and the diagnostics can still be saved as a file instead.'],
    ru: ['Сообщить о проблеме прямо из приложения: Настройки → «Сообщить о проблеме». Опишите, что случилось, и описание сразу уйдёт разработчику вместе с диагностикой (без ключей, токенов и паролей). Можно оставить контакт для ответа, а диагностику по-прежнему можно сохранить файлом.'],
    fr: ['Signalez un problème depuis l\'app : Réglages → Signaler un problème. Dites ce qui s\'est passé, et c\'est envoyé directement au développeur avec le diagnostic (sans clés, jetons ni mots de passe). Vous pouvez laisser un moyen de vous joindre, et le diagnostic peut toujours être enregistré en fichier.'] },
  { v: '0.4.1',
    en: ['Devices through OpenRGB that have no Direct mode (some ASRock graphics cards, for one) no longer just flash: haku lights them in their Static mode, a little slower, or with one colour, and leaves alone the ones it cannot light. The device\'s line says which.',
      'Each OpenRGB device has an Updates setting: if its lights still blink instead of moving smoothly, choose fewer updates per second.'],
    ru: ['Устройства через OpenRGB без режима Direct (например, некоторые видеокарты ASRock) больше не просто мигают: haku светит ими в их режиме Static, чуть медленнее, или одним цветом, а те, которыми управлять нельзя, не трогает. В строке устройства написано, как именно.',
      'У каждого устройства OpenRGB появилась настройка «Обновления»: если подсветка всё равно мигает вместо плавных эффектов, выберите меньше обновлений в секунду.'],
    fr: ['Les appareils passant par OpenRGB sans mode Direct (certaines cartes graphiques ASRock, par exemple) ne font plus que clignoter : haku les éclaire dans leur mode Static, un peu plus lentement, ou d\'une seule couleur, et laisse tranquilles ceux qu\'il ne peut pas éclairer. La ligne de l\'appareil indique lequel.',
      'Chaque appareil OpenRGB a un réglage Mises à jour : si ses lumières clignotent encore au lieu de bouger en douceur, choisissez moins de mises à jour par seconde.'] },
  { v: '0.4.0',
    en: ['haku Pro: the lights on Wi-Fi and the network (Nanoleaf, WLED, Hue, Govee, LIFX, Yeelight, WiZ, Elgato, Divoom, Tuya, AiDot) and phone control are now part of haku Pro, $2 a month or $10 a year. A free 14-day trial starts with this update, and Settings → haku Pro shows how many days are left. The PC\'s own lighting, USB devices, Razer, SteelSeries, Logitech and every effect stay free.',
      'The PC\'s lighting can be given back to the programs it came with (MSI Center, iCUE, Armoury Crate, Synapse...): Its own lighting on a device\'s card, or Give back to their apps on the PC tab (also in the tray menu). Its own effect comes back and haku leaves it alone until you take it again.',
      'Community: a new tab next to Effects and My presets with presets other people shared. Search, sort by popular or new, like, and add one in a click. Your own presets can be published from their Share window.',
      'Backup: Settings can save all of haku\'s setup to one file and bring it back on another PC (passwords and keys stay on this PC). Presets can be shared as a short code.',
      'Home Assistant (haku Pro): haku shows up as a light with its effects and brightness, and a profile picker, through MQTT.'],
    ru: ['haku Pro: лампы по Wi-Fi и в сети (Nanoleaf, WLED, Hue, Govee, LIFX, Yeelight, WiZ, Elgato, Divoom, Tuya, AiDot) и управление с телефона теперь входят в haku Pro — $2 в месяц или $10 в год. С этим обновлением начинается бесплатный пробный период на 14 дней; сколько дней осталось, видно в Настройках → haku Pro. Подсветка самого ПК, USB-устройства, Razer, SteelSeries, Logitech и все эффекты остаются бесплатными.',
      'Подсветку ПК можно вернуть её родным программам (MSI Center, iCUE, Armoury Crate, Synapse...): «Своя подсветка» в карточке устройства или «Вернуть родным программам» на вкладке ПК (и в меню трея). Возвращается её собственный эффект, и haku её не трогает, пока не заберёте обратно.',
      'Сообщество: новая вкладка рядом с «Эффектами» и «Моими пресетами» — пресеты, которыми поделились другие. Поиск, популярные и новые, лайки, добавление в один клик. Свои пресеты можно опубликовать из окна «Поделиться».',
      'Резервная копия: в Настройках можно сохранить всю настройку haku в один файл и восстановить её на другом ПК (пароли и ключи остаются на этом ПК). Пресетами можно делиться коротким кодом.',
      'Home Assistant (haku Pro): haku появляется там как лампа со своими эффектами и яркостью и с выбором профиля, через MQTT.'],
    fr: ['haku Pro : les lumières en Wi-Fi et sur le réseau (Nanoleaf, WLED, Hue, Govee, LIFX, Yeelight, WiZ, Elgato, Divoom, Tuya, AiDot) et le contrôle depuis le téléphone font désormais partie de haku Pro, 2 $ par mois ou 10 $ par an. Un essai gratuit de 14 jours commence avec cette mise à jour, et Réglages → haku Pro indique les jours restants. L\'éclairage du PC lui-même, les appareils USB, Razer, SteelSeries, Logitech et tous les effets restent gratuits.',
      'L\'éclairage du PC peut être rendu aux programmes livrés avec lui (MSI Center, iCUE, Armoury Crate, Synapse...) : Son propre éclairage sur la fiche d\'un appareil, ou Rendre à leurs apps dans l\'onglet PC (aussi dans le menu de la barre des tâches). Son propre effet revient et haku n\'y touche plus jusqu\'à ce que vous le repreniez.',
      'Communauté : un nouvel onglet à côté d\'Effets et Mes préréglages, avec les préréglages partagés par d\'autres. Recherche, populaires ou récents, j\'aime, et ajout en un clic. Vos propres préréglages se publient depuis leur fenêtre Partager.',
      'Sauvegarde : les Réglages enregistrent toute la configuration de haku dans un fichier et la restaurent sur un autre PC (mots de passe et clés restent sur ce PC). Les préréglages se partagent avec un code court.',
      'Home Assistant (haku Pro) : haku y apparaît comme une lumière avec ses effets et sa luminosité, et un choix de profil, via MQTT.'] },
  { v: '0.3.33',
    en: ['The devices in the preview can be put in your own order: choose Arrange in the preview\'s menu and drag a device onto another to swap their places. Dragging outside Arrange still makes a group.',
      'The theme switch in Settings no longer gets cut off when the window is narrow or the hidden themes are open: the buttons move under the label.'],
    ru: ['Устройства в превью можно расставить в своём порядке: выберите «Расставить» в меню превью и перетащите одно устройство на другое, чтобы поменять их местами. Перетаскивание без «Расставить» по-прежнему делает группу.',
      'Переключатель темы в настройках больше не обрезается в узком окне или когда открыты скрытые темы: кнопки переходят под надпись.'],
    fr: ['Les appareils de l\'aperçu se rangent dans votre ordre : choisissez Disposer dans le menu de l\'aperçu et glissez un appareil sur un autre pour les échanger de place. Glisser hors de Disposer crée toujours un groupe.',
      'Le choix du thème dans les Réglages n\'est plus coupé quand la fenêtre est étroite ou que les thèmes cachés sont ouverts : les boutons passent sous le libellé.'] },
  { v: '0.3.32',
    en: ['The hidden theme from 0.3.31 got prettier: its butterflies beat their wings, the light in the corner glows without a dark ring, and its name is written with a brush, stroke after stroke.'],
    ru: ['Скрытая тема из 0.3.31 стала красивее: бабочки машут крыльями, свет в углу светится без тёмного кольца, а её название пишется кистью, черта за чертой.'],
    fr: ['Le thème caché de la 0.3.31 est plus beau : ses papillons battent des ailes, la lumière du coin brille sans anneau sombre et son nom s\'écrit au pinceau, trait après trait.'] },
  { v: '0.3.31',
    en: ['A new hidden theme. Those who have its code will know what to type next to the theme switch.'],
    ru: ['Новая скрытая тема. У кого есть её код, тот знает, что вписать рядом с переключателем темы.'],
    fr: ['Un nouveau thème caché. Ceux qui ont son code savent quoi taper à côté du choix du thème.'] },
  { v: '0.3.30',
    en: ['Razer, SteelSeries and Logitech devices: with Razer Synapse, SteelSeries GG or Logitech G HUB running, Scan network offers their keyboards, mice, headsets and more; add the ones you have. Their own app gets the lighting back when haku lets go. New, so far tried only against stand-ins: reports are welcome.',
      'The effects tab switches between the effects and your own presets, so presets no longer get lost among the effects.',
      'Room for 32 devices instead of 16.'],
    ru: ['Устройства Razer, SteelSeries и Logitech: если запущен Razer Synapse, SteelSeries GG или Logitech G HUB, «Искать в сети» предлагает их клавиатуры, мыши, гарнитуры и другое; добавьте то, что у вас есть. Когда haku их отпускает, подсветку забирает их собственное приложение. Это новое и пока проверено только на имитациях: напишите, как работает.',
      'На вкладке эффектов есть переключатель «Эффекты / Мои пресеты», пресеты больше не теряются среди эффектов.',
      'Можно добавить 32 устройства вместо 16.'],
    fr: ['Appareils Razer, SteelSeries et Logitech : avec Razer Synapse, SteelSeries GG ou Logitech G HUB lancé, Analyser le réseau propose leurs claviers, souris, casques et plus ; ajoutez ceux que vous avez. Leur propre app reprend l\'éclairage quand haku les libère. Nouveau, essayé seulement sur des imitations : vos retours sont bienvenus.',
      'L\'onglet des effets bascule entre les effets et vos préréglages, qui ne se perdent plus parmi les effets.',
      'Place pour 32 appareils au lieu de 16.'] },
  { v: '0.3.29',
    en: ['New effect: Screen (ambilight). The lights follow what is on the screen: strips run around its edges, a Nanoleaf wall or a keyboard shows it as a mosaic, single lights take its average colour. Each device can take another part of the screen; it barely uses the PC.'],
    ru: ['Новый эффект: Экран (эмбилайт). Свет повторяет то, что на экране: ленты идут по его краям, стена Nanoleaf или клавиатура показывают его мозаикой, одиночные лампы берут средний цвет. Каждому устройству можно задать свою часть экрана; ПК почти не нагружается.'],
    fr: ['Nouvel effet : Écran (ambilight). Les lumières suivent ce qui est à l\'écran : les bandes en font le tour, un mur Nanoleaf ou un clavier le montre en mosaïque, les lampes seules prennent sa couleur moyenne. Chaque appareil peut prendre une autre partie de l\'écran ; le PC n\'est presque pas sollicité.'] },
  { v: '0.3.28',
    en: ['Every brand of lights you add gets its own tab in the sidebar, as Nanoleaf has: WLED, Govee, LIFX, Yeelight, Hue, WiZ, Tuya, Elgato, Divoom. PC hardware and finding new devices stay under Devices.'],
    ru: ['У каждого добавленного бренда света теперь своя вкладка в левой панели, как у Nanoleaf: WLED, Govee, LIFX, Yeelight, Hue, WiZ, Tuya, Elgato, Divoom. Железо ПК и поиск новых устройств остаются в «Устройствах».'],
    fr: ['Chaque marque de lumières ajoutée a maintenant son onglet dans la barre latérale, comme Nanoleaf : WLED, Govee, LIFX, Yeelight, Hue, WiZ, Tuya, Elgato, Divoom. Le matériel du PC et la recherche d\'appareils restent dans Appareils.'] },
  { v: '0.3.27',
    en: ['Nanoleaf Shapes triangles are drawn the right way round in the preview (they used to come out turned over), mirrored layouts included.'],
    ru: ['Треугольники Nanoleaf Shapes рисуются в превью правильной стороной (раньше выходили перевёрнутыми), в том числе в зеркальных раскладках.'],
    fr: ['Les triangles Nanoleaf Shapes sont dessinés dans le bon sens dans l\'aperçu (ils sortaient retournés), dispositions en miroir comprises.'] },
  { v: '0.3.26',
    en: ['The PC tab is now on every PC, not only with an MSI board or RGB memory: Lighting in this PC and the OpenRGB set-up are there for any hardware. The Memory and ARGB strip cards show only where that hardware is found.',
      'Clicking the memory or the ARGB strip in the preview opens the right card again.'],
    ru: ['Вкладка «ПК» теперь есть на любом компьютере, а не только с платой MSI или RGB-памятью: «Подсветка в этом ПК» и установка OpenRGB доступны для любого железа. Карточки «Память» и ARGB-ленты показываются, только если такое железо найдено.',
      'Клик по памяти или ARGB-ленте в превью снова открывает нужную карточку.'],
    fr: ['L\'onglet PC est maintenant là sur tous les PC, pas seulement avec une carte mère MSI ou de la mémoire RGB : l\'éclairage de ce PC et l\'installation d\'OpenRGB servent pour tout matériel. Les cartes Mémoire et bande ARGB n\'apparaissent que si ce matériel est trouvé.',
      'Un clic sur la mémoire ou la bande ARGB dans l\'aperçu ouvre de nouveau la bonne carte.'] },
  { v: '0.3.25',
    en: ['Ten new effects: Rainbow, Fire, Ocean, Twinkle, Meteor, Plasma, Aurora, Ripple, Matrix and Candle. They span every device as one picture (Nanoleaf included), each with its own colours, which you can change.',
      'A device\'s own brightness now goes down to 1%, and Elgato Key Lights to 3%, as in Elgato\'s app.'],
    ru: ['Десять новых эффектов: Радуга, Огонь, Океан, Мерцание, Метеор, Плазма, Северное сияние, Капли, Матрица и Свеча. Они идут через все устройства одной картинкой (включая Nanoleaf), у каждого свои цвета, их можно поменять.',
      'Своя яркость устройства теперь опускается до 1%, а у Elgato Key Light — до 3%, как в приложении Elgato.'],
    fr: ['Dix nouveaux effets : Arc-en-ciel, Feu, Océan, Scintillement, Météore, Plasma, Aurore, Gouttes, Matrice et Bougie. Ils parcourent tous les appareils comme une seule image (Nanoleaf compris), chacun avec ses couleurs, modifiables.',
      'La luminosité propre d\'un appareil descend maintenant à 1 %, et les Elgato Key Light à 3 %, comme dans l\'app Elgato.'] },
  { v: '0.3.24',
    en: ['Show in the preview: every device has its own line now, so a graphics card or a lamp can be left out on its own.',
      'After installing or updating by hand, haku\'s window opens by itself (with what is new).',
      'Nanoleaf Shapes: hexagons next to triangles are no longer drawn turned in the preview.'],
    ru: ['«Показывать в превью»: у каждого устройства теперь своя галочка, можно убрать отдельно видеокарту или лампу.',
      'После ручной установки или обновления окно haku открывается само (с «Что нового»).',
      'Nanoleaf Shapes: шестиугольники рядом с треугольниками больше не рисуются повёрнутыми в превью.'],
    fr: ['Afficher dans l\'aperçu : chaque appareil a maintenant sa ligne, une carte graphique ou une lampe peut être retirée seule.',
      'Après une installation ou une mise à jour à la main, la fenêtre de haku s\'ouvre toute seule (avec les nouveautés).',
      'Nanoleaf Shapes : les hexagones à côté de triangles ne sont plus dessinés tournés dans l\'aperçu.'] },
  { v: '0.3.23',
    en: ['Lighting in this PC (PC tab, at the top): haku finds the board, the memory, the graphics cards and the USB lighting devices, and says for each how it is lit: by haku itself, through OpenRGB, or what is still missing (with the button for it).',
      'After an update installed by hand, haku starts by itself again.'],
    ru: ['Подсветка в этом ПК (вкладка «ПК», сверху): haku находит плату, память, видеокарты и USB-устройства с подсветкой и показывает, как подсвечивается каждое: самой haku, через OpenRGB, или чего ещё не хватает (с кнопкой для этого).',
      'После обновления, установленного вручную, haku снова запускается сама.'],
    fr: ['L\'éclairage de ce PC (onglet PC, en haut) : haku trouve la carte mère, la mémoire, les cartes graphiques et les appareils USB éclairés, et dit pour chacun comment il est éclairé : par haku, via OpenRGB, ou ce qui manque encore (avec le bouton pour ça).',
      'Après une mise à jour installée à la main, haku redémarre tout seul.'] },
  { v: '0.3.22',
    en: ['Divoom Times Gate and Times Frame: the screens stay off with the lights (they used to come back on right away).'],
    ru: ['Divoom Times Gate и Times Frame: экраны остаются выключенными вместе со светом (раньше сразу включались обратно).'],
    fr: ['Divoom Times Gate et Times Frame : les écrans restent éteints avec l\'éclairage (ils se rallumaient aussitôt).'] },
  { v: '0.3.21',
    en: ['Divoom Times Frame: its side light follows haku. Pick the light effect by number in its card (they have no names yet).',
      'Divoom Times Frame screen: leave it as it is, show a Divoom dial, or haku\'s own screen with the time, CPU, memory, the effect and the profile. Each profile keeps its own.',
      'Divoom Times Gate and Times Frame: the screens go off with the lights (can be turned off in the device\'s card).'],
    ru: ['Divoom Times Frame: боковая подсветка следует за haku. Эффект подсветки выбирается по номеру в карточке (названий у них пока нет).',
      'Экран Divoom Times Frame: оставить как есть, показать циферблат Divoom или экран haku со временем, CPU, памятью, эффектом и профилем. У каждого профиля свой.',
      'Divoom Times Gate и Times Frame: экраны гаснут вместе со светом (отключается в карточке устройства).'],
    fr: ['Divoom Times Frame : son éclairage latéral suit haku. L\'effet se choisit par numéro dans sa carte (ils n\'ont pas encore de nom).',
      'Écran de la Divoom Times Frame : le laisser tel quel, afficher un cadran Divoom, ou l\'écran de haku avec l\'heure, le CPU, la mémoire, l\'effet et le profil. Chaque profil garde le sien.',
      'Divoom Times Gate et Times Frame : les écrans s\'éteignent avec l\'éclairage (désactivable dans la carte de l\'appareil).'] },
  { v: '0.3.20',
    en: ['Updates keep coming even after "Check now" is pressed many times: GitHub limits how often it may be asked, so haku asks at most once a minute and, when GitHub says no, finds the new version another way.',
      'Divoom Times Frame: haku looks for the command its lights take. If they stay dark, the diagnostics now show what it tried.'],
    ru: ['Обновления приходят, даже если много раз нажать «Проверить»: GitHub ограничивает, как часто его можно спрашивать, поэтому haku спрашивает не чаще раза в минуту, а если GitHub отказал, находит новую версию другим путём.',
      'Divoom Times Frame: haku ищет команду, которую принимает его подсветка. Если она не загорается, в диагностике теперь видно, что было испробовано.'],
    fr: ['Les mises à jour arrivent même après de nombreux « Vérifier » : GitHub limite la fréquence des demandes, alors haku demande au plus une fois par minute et, si GitHub refuse, trouve la nouvelle version autrement.',
      'Divoom Times Frame : haku cherche la commande que prend son éclairage. S\'il reste éteint, le diagnostic montre maintenant ce qui a été essayé.'] },
  { v: '0.3.19',
    en: ['Divoom Times Frame connects (it was wrongly told its LocalToken was wrong).',
      'Divoom devices are found more reliably when Divoom\'s service misses them for a moment.'],
    ru: ['Divoom Times Frame подключается (раньше haku ошибочно писала, что LocalToken неверный).',
      'Устройства Divoom находятся надёжнее, когда сервис Divoom на миг их не видит.'],
    fr: ['La Divoom Times Frame se connecte (haku disait à tort que son LocalToken était faux).',
      'Les appareils Divoom sont trouvés plus sûrement quand le service de Divoom les rate un instant.'] },
  { v: '0.3.18',
    en: ['Divoom Times Gate: the side lights follow haku too. Its card says which lights take haku\'s colours (back and sides, back only, sides only…).',
      'Divoom Times Gate keeps its connection when it misses an answer now and then.',
      'Divoom Times Frame: found and connected, with its own type. Its lights are still being found out: if they stay dark, send the diagnostics.'],
    ru: ['Divoom Times Gate: боковая подсветка тоже следует за haku. В карточке можно выбрать, какая подсветка берёт цвета haku (задняя и боковая, только задняя, только боковая…).',
      'Divoom Times Gate больше не отваливается, когда изредка не отвечает.',
      'Divoom Times Frame находится и подключается, у него свой тип. Его подсветку ещё изучаем: если она не загорается, пришлите диагностику.'],
    fr: ['Divoom Times Gate : l\'éclairage latéral suit haku lui aussi. Sa carte indique quels éclairages prennent les couleurs de haku (arrière et côtés, arrière seul, côtés seuls…).',
      'La Divoom Times Gate garde sa connexion quand elle manque une réponse de temps en temps.',
      'Divoom Times Frame : trouvé et connecté, avec son propre type. Son éclairage est encore à l\'étude : s\'il reste éteint, envoyez le diagnostic.'] },
  { v: '0.3.17',
    en: ['Divoom: a scan finds them (through Divoom\'s own service, like the Divoom app), and a device can be added by its Device ID as well as by its IP. The LocalToken is still needed.',
      'Hidden themes play their animations even when Windows\' animation effects are off (haku\'s own Animations switch still stops them).'],
    ru: ['Divoom: поиск находит их (через сервис самой Divoom, как приложение Divoom), а добавить устройство можно не только по IP, но и по Device ID. LocalToken по-прежнему нужен.',
      'Скрытые темы показывают свои анимации, даже когда в Windows выключены эффекты анимации (переключатель «Анимации» в haku их по-прежнему останавливает).'],
    fr: ['Divoom : une recherche les trouve (via le service de Divoom, comme l\'app Divoom), et un appareil peut être ajouté par son Device ID aussi bien que par son IP. Le LocalToken reste nécessaire.',
      'Les thèmes cachés jouent leurs animations même quand les effets d\'animation de Windows sont désactivés (l\'interrupteur Animations de haku les arrête toujours).'] },
  { v: '0.3.16',
    en: ['Next to the theme switch there is now a field for secret codes. What they open is for you to find out 👀'],
    ru: ['Рядом с выбором темы появилось поле для секретных кодов. Что они открывают — узнаете сами 👀'],
    fr: ['À côté du choix du thème, il y a maintenant un champ pour des codes secrets. Ce qu\'ils ouvrent, à vous de le découvrir 👀'] },
  { v: '0.3.15',
    en: ['Updates install by themselves: haku checks every few hours and updates when a new version is out, after a notice from the tray (never during a full-screen game or a presentation).'],
    ru: ['Обновления ставятся сами: haku проверяет каждые несколько часов и обновляется, когда выходит новая версия, предупредив уведомлением из трея (никогда во время полноэкранной игры или презентации).'],
    fr: ['Les mises à jour s\'installent toutes seules : haku vérifie toutes les quelques heures et se met à jour quand une nouvelle version sort, après une notification (jamais pendant un jeu en plein écran ou une présentation).'] },
  { v: '0.3.14',
    en: ['Device settings show only what the device can do: an Elgato Key Light or Ring Light gets its colour temperature (2900–7000 K) and brightness, no effects or palettes.',
      'A Govee sync box in its own screen-sync mode shows just how to switch it to haku\'s colours.',
      'Groups no longer push colours or effects onto white-only lights.',
      'This window: after an update haku shows what is new. Open it again under Settings → What is new.'],
    ru: ['В настройках устройства теперь только то, что оно умеет: у Elgato Key Light и Ring Light — температура белого (2900–7000 K) и яркость, без эффектов и палитр.',
      'Для Govee Sync Box в режиме своей синхронизации с экраном — только подсказка, как переключить его на цвета haku.',
      'Группы больше не навязывают цвета и эффекты лампам, которые светят только белым.',
      'Это окно: после обновления haku показывает, что нового. Открыть снова — «Настройки» → «Что нового».'],
    fr: ['Les réglages d\'un appareil ne montrent que ce qu\'il sait faire : une Elgato Key Light ou Ring Light n\'a que sa température de couleur (2900–7000 K) et sa luminosité, sans effets ni palettes.',
      'Une sync box Govee dans son propre mode (synchro écran) indique juste comment passer aux couleurs de haku.',
      'Les groupes n\'imposent plus couleurs ni effets aux lampes qui ne font que du blanc.',
      'Cette fenêtre : après une mise à jour, haku montre les nouveautés. Pour la rouvrir : Réglages → Nouveautés.'] },
  { v: '0.3.13',
    en: ['OpenRGB by itself: PC → Other PC hardware → "Download and set up OpenRGB". haku downloads it, starts it hidden and adds the graphics cards, boards and RAM it finds.',
      'Themes: dark, grey and light (Settings → General → Theme).',
      'French language.'],
    ru: ['OpenRGB сам по себе: «ПК» → «Другое оборудование ПК» → «Скачать и настроить OpenRGB». haku скачивает его, скрыто запускает и добавляет найденные видеокарты, платы и память.',
      'Темы: тёмная, серая и светлая («Настройки» → «Общие» → «Тема»).',
      'Французский язык.'],
    fr: ['OpenRGB tout seul : PC → Autre matériel du PC → « Télécharger et configurer OpenRGB ». haku le télécharge, le lance en arrière-plan et ajoute les cartes graphiques, cartes mères et RAM qu\'il trouve.',
      'Thèmes : sombre, gris et clair (Réglages → Général → Thème).',
      'Langue française.'] },
  { v: '0.3.12',
    en: ['Elgato Key Lights now react (they were found but ignored the commands).',
      'haku checks a list of versions the author has stopped supporting, signed by the author; such a version shows a message with a download link.'],
    ru: ['Elgato Key Light теперь реагируют (раньше находились, но не слушались команд).',
      'haku сверяется со списком версий, которые автор больше не поддерживает (список подписан автором); такая версия показывает сообщение со ссылкой на загрузку.'],
    fr: ['Les Elgato Key Light réagissent enfin (elles étaient trouvées mais ignoraient les commandes).',
      'haku consulte une liste, signée par l\'auteur, des versions qui ne sont plus prises en charge ; une telle version affiche un message avec un lien de téléchargement.'] },
  { v: '0.3.11',
    en: ['The AI colour picker keeps its model in memory only while it works; "Ollama only when needed" keeps Ollama out of Windows startup.',
      'One-click setup of Ollama and the model under Settings.',
      'Divoom Times Gate lights (experimental).'],
    ru: ['Подбор цветов ИИ держит модель в памяти только пока работает; «Ollama только по запросу» убирает Ollama из автозагрузки Windows.',
      'Установка Ollama и модели одной кнопкой в «Настройках».',
      'Подсветка Divoom Times Gate (экспериментально).'],
    fr: ['Le choix des couleurs par IA ne garde son modèle en mémoire que pendant qu\'il travaille ; « Ollama seulement quand il faut » retire Ollama du démarrage de Windows.',
      'Installation d\'Ollama et du modèle en un clic dans les Réglages.',
      'Éclairage du Divoom Times Gate (expérimental).'] },
  { v: '0.3.10',
    en: ['Wooting keyboards directly over USB.'],
    ru: ['Клавиатуры Wooting напрямую по USB.'],
    fr: ['Claviers Wooting directement en USB.'] },
  { v: '0.3.9',
    en: ['Profiles: the whole setup for a scenario (gaming, work, night…), switched above the widgets, from the tray or by hotkey.',
      'Elgato Key Light, Ring Light and Light Strip.'],
    ru: ['Профили: весь набор настроек под сценарий (игра, работа, ночь…), переключение над виджетами, в трее или горячей клавишей.',
      'Elgato Key Light, Ring Light и Light Strip.'],
    fr: ['Profils : toute la configuration d\'un scénario (jeu, travail, nuit…), à changer au-dessus des widgets, depuis la barre des tâches ou par raccourci.',
      'Elgato Key Light, Ring Light et Light Strip.'] },
];
